few_shot_examples = [
    {
        "question": "What is the shipping cost?",
        "context": "[1] Standard shipping costs five dollars for all domestic orders.",
        "answer": "Standard shipping costs five dollars [1].",
    },
    {
        "question": "What is the warranty period for electronics?",
        "context": "[1] Refunds are processed within five business days.",
        "answer": "I don't have enough information to answer that.",
    },
]

def build_few_shot_prompt(examples, real_context, real_query):
    # each example pairs a question, context, and ideal answer
    example_blocks = []
    for ex in examples:
        example_blocks.append(
            f"Question: {ex['question']}\nContext: {ex['context']}\nAnswer: {ex['answer']}"
        )
    examples_section = "\n\n".join(example_blocks)

    return (
        f"Here are some examples of how to answer:\n\n{examples_section}\n\n"
        f"Now answer this question:\nContext: {real_context}\nQuestion: {real_query}\nAnswer:"
    )

real_context = "[1] Refunds are processed within five business days."
real_query = "How long does a refund take?"

prompt = build_few_shot_prompt(few_shot_examples, real_context, real_query)
print("Few-shot prompt:\n")
print(prompt)

print(f"\nApproximate example token cost: {sum(len(str(ex).split()) for ex in few_shot_examples)} words")
